    pub fn camp_party(&self) -> bool {
        self.base.camp_party()
    }

    /// Record every visible hostile military unit as it stands right now, so
    /// a civilian's step keeps pricing one the planning board kills before
    /// the civilian moves. Idempotent within a turn: the first caller wins —
    /// the live bridge calls it before its finishing volley, `take_turn`
    /// calls it as a fallback. A no-op unless `settler_stack_discipline`.
    pub fn observe_turn_start_hostiles(&mut self, g: &Game, pid: usize) {
        // Hostile memory rides the same observation point and nothing else:
        // this is the one call every seat makes before it has moved anything,
        // so it is the only place on the board where "what the seat could see
        // at the start of its turn" is still true. The live capture lessons
        // use the same bounded memory for barbarian sightings, while the
        // opt-in `hostile-memory` gene additionally widens the owner scope on
        // native/evaluator boards.
        if self.hostile_memory
            || self.hostile_memory_2
            || self.hostile_memory_3
            || self.live_settler_capture_lessons
            || self.staging_gun_remembers_hostiles
        {
            self.remember_visible_hostiles(g, pid);
        }
        // `capital-walls-before-the-surprise`: the watched majors' soldiers
        // near the original capital, from the same turn-start frame.
        self.remember_capital_watch_sightings(g, pid);
        self.remember_frontier_watch_sightings(g, pid);
        // `surprise-watch-holds-its-ratio`: see `advanced/surprise_watch_latch.rs`.
        self.remember_surprise_watch_latches(g, pid);
        if !self.live_formationless_settler_shadow || self.turn_start_hostiles_turn == Some(g.turn)
        {
            return;
        }
        self.turn_start_hostiles_turn = Some(g.turn);
        self.turn_start_hostiles.clear();
        let visible = g.player_vision_frame(pid);
        for unit in g.units.values() {
            if unit.owner == pid
                || !g.is_at_war(pid, unit.owner)
                || !g.sees(&visible, unit.pos)
                || !g.unit_visible_to(unit.id, pid)
            {
                continue;
            }
            let spec = &g.rules.units[unit.kind];
            if spec.class != "military" || spec.domain.as_deref() == Some("air") {
                continue;
            }
            if self.barbarian_scouts_are_scouts
                && !self.live_barbarian_scouts_capture
                && g.players[unit.owner].is_barbarian
                && spec.promotion_class == "recon"
            {
                continue;
            }
            self.turn_start_hostiles.push(TurnStartHostile {
                id: unit.id,
                host_key: hostile_memory_key(g, unit),
                owner: unit.owner,
                pos: unit.pos,
                capture_reach: spec.moves.ceil() as i32,
                strength: crate::game::effective_strength(g.unit_strength(unit, false), unit.hp)
                    .max(1.0),
                sea: spec.domain.as_deref() == Some("sea"),
            });
        }
    }

    /// Remember where every in-scope military unit the seat can see right now
    /// is standing, and forget anything older than
    /// [`civilian_safety::HOSTILE_MEMORY_TURNS`]. `hostile-memory` includes
    /// every at-war owner; the live capture lessons retain barbarian sightings
    /// without changing the native owner scope.
    ///
    /// The recorded fact is deliberately only what the seat SAW: the position,
    /// turn, owner and unit kind. `barbarian_reach` projects the envelope from
    /// that tile and never asks the unit where it really is, which is the
    /// difference between remembering a raider and reading the fog.
    fn remember_visible_hostiles(&mut self, g: &Game, pid: usize) {
        self.hostile_last_seen.retain(|_, record| {
            record.when <= g.turn && g.turn - record.when <= civilian_safety::HOSTILE_MEMORY_TURNS
        });
        // `unit_visible_to` checks stealth detection, not tile visibility.
        // The native board also contains ordinary enemies still in the fog.
        let visible = g.player_vision_frame(pid);
        for unit in g.units.values() {
            if unit.owner == pid
                || !g.is_at_war(pid, unit.owner)
                || !g.sees(&visible, unit.pos)
                || !g.unit_visible_to(unit.id, pid)
            {
                continue;
            }
            let spec = &g.rules.units[unit.kind];
            if spec.class != "military" || spec.domain.as_deref() == Some("air") {
                continue;
            }
            let key = hostile_memory_key(g, unit);
            self.hostile_last_seen.insert(
                key,
                RememberedHostile {
                    pos: unit.pos,
                    when: g.turn,
                    owner: unit.owner,
                    kind: unit.kind,
                },
            );
        }
        if self.hostile_memory_3 {
            self.forget_cleared_hostile_sightings(g, &visible);
        }
    }

    /// The guards currently bound to a living settler of `pid` under
    /// `stacked_escort`. Under `settler_stack_discipline` they stay out of
    /// attack work that runs before the settler moves, including the live
    /// bridge's finishing volley, so a guard is not spent one tile away from
    /// the civilian it shields. Empty when the discipline is off.
    pub fn bound_settler_guards(&self, g: &Game, pid: usize) -> BTreeSet<u32> {
        if !self.live_formationless_settler_shadow {
            return BTreeSet::new();
        }
        self.settler_guards
            .iter()
            .chain(self.settler_sea_guards.iter())
            .filter(|(settler, _)| {
                g.units
                    .get(settler)
                    .is_some_and(|unit| unit.owner == pid && unit.kind == "settler")
            })
            .map(|(_, guard)| *guard)
            .filter(|guard| g.units.get(guard).is_some_and(|unit| unit.owner == pid))
            .collect()
    }

